package vn.ktd.taskhub.client.feature.group.view;

import com.google.gson.*;
import java.awt.*;
import java.awt.event.*;
import java.io.IOException;
import java.util.concurrent.Callable;
import java.util.function.Consumer;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import vn.ktd.taskhub.client.network.GroupApiClient;
import vn.ktd.taskhub.client.network.GroupApiClient.ApiException;

public final class GroupsFrame extends JFrame {
    private static final long serialVersionUID = 1L;
    private final transient GroupApiClient api;
    private final DefaultListModel<JsonObject> groups=new DefaultListModel<>();
    private final JList<JsonObject> groupList=new JList<>(groups);
    private final DefaultTableModel invites=new DefaultTableModel(new Object[]{"ID","Nhóm","Người mời","Hết hạn"},0){public boolean isCellEditable(int r,int c){return false;}};
    private final JTable inviteTable=new JTable(invites);
    private final JLabel status=new JLabel(" ");

    public GroupsFrame(GroupApiClient api,String fullName){super("KTD Task Hub - Nhóm của tôi");this.api=api;build(fullName);refresh();}

    private void build(String fullName){
        setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);setSize(980,680);setLocationRelativeTo(null);
        addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){try{api.close();}catch(IOException ignored){}dispose();}});
        JPanel header=new JPanel(new BorderLayout(12,12));JLabel title=new JLabel("Nhóm của tôi - "+fullName);title.setFont(title.getFont().deriveFont(Font.BOLD,22f));header.add(title,BorderLayout.WEST);
        JPanel buttons=new JPanel(new FlowLayout(FlowLayout.RIGHT));buttons.add(button("Tham gia bằng mã",e->join()));buttons.add(button("+ Tạo nhóm",e->create()));buttons.add(button("Làm mới",e->refresh()));header.add(buttons,BorderLayout.EAST);
        groupList.setCellRenderer((list,value,index,selected,focus)->{JLabel l=new JLabel("<html><b>"+html(text(value,"name"))+"</b><br>"+role(value)+" · "+text(value,"memberCount")+" thành viên · "+text(value,"status")+"</html>");l.setOpaque(true);l.setBorder(BorderFactory.createEmptyBorder(10,12,10,12));l.setBackground(selected?new Color(220,228,255):Color.WHITE);return l;});
        groupList.addMouseListener(new MouseAdapter(){public void mouseClicked(MouseEvent e){if(e.getClickCount()==2)openSelected();}});
        JPanel center=new JPanel(new GridLayout(1,2,16,0));JPanel groupPanel=new JPanel(new BorderLayout());groupPanel.setBorder(BorderFactory.createTitledBorder("Danh sách nhóm"));groupPanel.add(new JScrollPane(groupList));groupPanel.add(button("Mở nhóm",e->openSelected()),BorderLayout.SOUTH);center.add(groupPanel);
        JPanel invitationPanel=new JPanel(new BorderLayout(6,6));invitationPanel.setBorder(BorderFactory.createTitledBorder("Lời mời đang chờ"));invitationPanel.add(new JScrollPane(inviteTable));JPanel actions=new JPanel();actions.add(button("Chấp nhận",e->respondInvite("accept")));actions.add(button("Từ chối",e->respondInvite("decline")));invitationPanel.add(actions,BorderLayout.SOUTH);center.add(invitationPanel);
        JPanel root=new JPanel(new BorderLayout(12,12));root.setBorder(BorderFactory.createEmptyBorder(16,16,12,16));root.add(header,BorderLayout.NORTH);root.add(center);root.add(status,BorderLayout.SOUTH);setContentPane(root);
    }

    private void refresh(){async(()->{JsonObject o=api.request("GROUP_LIST",new JsonObject());o.add("invitations",api.request("GROUP_INVITATION_LIST",new JsonObject()).get("invitations"));return o;},o->{groups.clear();for(JsonElement e:o.getAsJsonArray("groups"))groups.addElement(e.getAsJsonObject());fill(invites,o.getAsJsonArray("invitations"),iv->new Object[]{longValue(iv,"invitationId"),text(iv,"groupName"),text(iv,"fullName"),text(iv,"expiresAt")});status.setText("Đã tải "+groups.size()+" nhóm");});}

    private void create(){JTextField name=new JTextField();JTextArea desc=new JTextArea(3,24);JCheckBox approval=new JCheckBox("Bật duyệt thành viên",true);Object[] fields={"Tên nhóm (3-50 ký tự)",name,"Mô tả",new JScrollPane(desc),approval};if(JOptionPane.showConfirmDialog(this,fields,"Tạo nhóm",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;JsonObject d=new JsonObject();d.addProperty("name",name.getText());d.addProperty("description",desc.getText());d.addProperty("approvalEnabled",approval.isSelected());async(()->api.request("GROUP_CREATE",d),o->{JOptionPane.showMessageDialog(this,"Đã tạo nhóm. Mã gia nhập: "+text(o,"inviteCode"));refresh();});}
    private void join(){String code=JOptionPane.showInputDialog(this,"Nhập mã gia nhập 12 ký tự","Tham gia nhóm",JOptionPane.PLAIN_MESSAGE);if(code==null)return;JsonObject d=new JsonObject();d.addProperty("inviteCode",code.trim());async(()->api.request("GROUP_JOIN",d),o->{JOptionPane.showMessageDialog(this,"Kết quả: "+text(o,"status"));refresh();});}
    private void respondInvite(String decision){int row=inviteTable.getSelectedRow();if(row<0){warn("Chọn một lời mời");return;}JsonObject d=new JsonObject();d.addProperty("invitationId",((Number)invites.getValueAt(row,0)).longValue());d.addProperty("decision",decision);async(()->api.request("GROUP_INVITE_RESPOND",d),o->refresh());}
    private void openSelected(){JsonObject g=groupList.getSelectedValue();if(g==null){warn("Chọn một nhóm");return;}new GroupDialog(this,api,longValue(g,"groupId")).setVisible(true);refresh();}

    private void async(Callable<JsonObject> work,Consumer<JsonObject> done){status.setText("Đang xử lý...");new SwingWorker<JsonObject,Void>(){protected JsonObject doInBackground()throws Exception{return work.call();}protected void done(){try{JsonObject value=get();done.accept(value);status.setText("Sẵn sàng");}catch(Exception e){showError(e);}}}.execute();}
    private void showError(Exception error){Throwable t=error;while(t.getCause()!=null)t=t.getCause();String message=t instanceof ApiException a?friendly(a.code(),a.getMessage()):t.getMessage();status.setText("Lỗi: "+message);JOptionPane.showMessageDialog(this,message,"Không thể thực hiện",JOptionPane.ERROR_MESSAGE);}
    private static JButton button(String label,ActionListener listener){JButton b=new JButton(label);b.addActionListener(listener);return b;}
    private void warn(String text){JOptionPane.showMessageDialog(this,text,"KTD Task Hub",JOptionPane.WARNING_MESSAGE);}
    private static String friendly(String code,String fallback){return switch(code){case"AUTH_REQUIRED"->"Bạn cần đăng nhập lại.";case"FORBIDDEN"->"Bạn không có quyền thực hiện.";case"NOT_MEMBER"->"Bạn không còn là thành viên nhóm.";case"GROUP_DISBANDED"->"Nhóm đã giải tán và chỉ được xem.";case"DUPLICATE_GROUP_NAME"->"Bạn đã có nhóm cùng tên.";case"INVALID_JOIN_CODE"->"Mã gia nhập không đúng hoặc đã bị thu hồi.";case"JOIN_RATE_LIMITED"->"Bạn đã nhập sai quá nhiều lần. Hãy thử lại sau 15 phút.";case"BLOCKED"->"Tài khoản đang bị chặn khỏi nhóm.";case"ALREADY_MEMBER"->"Bạn đã là thành viên nhóm.";case"OPEN_TASKS_EXIST"->"Còn công việc mở; cần hoàn thành hoặc bàn giao trước.";case"ROLE_TRANSFER_REQUIRED"->"Trưởng nhóm phải chuyển quyền trước khi rời.";case"DEPENDENCY_UNAVAILABLE"->"Phần đổi người phụ trách của TV3 chưa được tích hợp.";case"CONFLICT"->"Dữ liệu vừa thay đổi. Hãy tải lại.";default->fallback;};}
    private static String text(JsonObject o,String key){JsonElement e=o==null?null:o.get(key);return e==null||e.isJsonNull()?"":e.getAsString();}
    private static long longValue(JsonObject o,String key){return o.get(key).getAsLong();}
    private static String role(JsonObject o){String r=text(o,"role");return "leader".equals(r)?"Trưởng nhóm":"member".equals(r)?"Thành viên":"Chờ duyệt";}
    private static String html(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
    private interface RowMapper{Object[] map(JsonObject value);}
    private static void fill(DefaultTableModel model,JsonArray values,RowMapper mapper){model.setRowCount(0);if(values!=null)for(JsonElement e:values)model.addRow(mapper.map(e.getAsJsonObject()));}

    private static final class GroupDialog extends JDialog {
        private static final long serialVersionUID = 1L;
        private final transient GroupApiClient api;private final long groupId;private transient JsonObject detail;private final JLabel heading=new JLabel();private final JLabel status=new JLabel(" ");private final transient java.util.List<AbstractButton> leaderButtons=new java.util.ArrayList<>();private final transient java.util.List<AbstractButton> activeButtons=new java.util.ArrayList<>();
        private final DefaultTableModel members=new DefaultTableModel(new Object[]{"User ID","MSSV","Họ tên","Vai trò","Online","Task mở"},0){public boolean isCellEditable(int r,int c){return false;}};
        private final DefaultTableModel requests=new DefaultTableModel(new Object[]{"ID","User ID","MSSV","Họ tên","Trạng thái","Thời gian"},0){public boolean isCellEditable(int r,int c){return false;}};
        private final DefaultTableModel blocks=new DefaultTableModel(new Object[]{"User ID","MSSV","Họ tên","Thời gian chặn"},0){public boolean isCellEditable(int r,int c){return false;}};
        private final DefaultTableModel handovers=new DefaultTableModel(new Object[]{"ID","Task","Người yêu cầu","Người gợi ý","Lý do","Trạng thái"},0){public boolean isCellEditable(int r,int c){return false;}};
        private final DefaultTableModel outgoing=new DefaultTableModel(new Object[]{"ID","MSSV","Họ tên","Trạng thái","Hết hạn"},0){public boolean isCellEditable(int r,int c){return false;}};
        private final JTable memberTable=new JTable(members),requestTable=new JTable(requests),blockTable=new JTable(blocks),handoverTable=new JTable(handovers),outgoingTable=new JTable(outgoing);
        private final JTextField name=new JTextField();private final JTextArea description=new JTextArea(4,30);private final JCheckBox approval=new JCheckBox("Bật duyệt thành viên tham gia");private final JLabel code=new JLabel();

        GroupDialog(Frame owner,GroupApiClient api,long groupId){super(owner,"Quản lý nhóm",true);this.api=api;this.groupId=groupId;build();refresh();}
        private void build(){setSize(1040,720);setLocationRelativeTo(getOwner());setLayout(new BorderLayout(8,8));heading.setFont(heading.getFont().deriveFont(Font.BOLD,20f));JPanel top=new JPanel(new BorderLayout());top.setBorder(BorderFactory.createEmptyBorder(10,12,0,12));top.add(heading);top.add(button("Làm mới",e->refresh()),BorderLayout.EAST);add(top,BorderLayout.NORTH);JTabbedPane tabs=new JTabbedPane();tabs.addTab("Thành viên",membersPanel());tabs.addTab("Yêu cầu",requestsPanel());tabs.addTab("Cài đặt",settingsPanel());tabs.addTab("Bị chặn",blocksPanel());tabs.addTab("Bàn giao",handoverPanel());add(tabs);status.setBorder(BorderFactory.createEmptyBorder(4,12,8,12));add(status,BorderLayout.SOUTH);}
        private JPanel membersPanel(){JPanel p=panel(memberTable);JPanel a=new JPanel();a.add(leaderButton("Mời",e->invite()));a.add(leaderButton("Thu hồi lời mời",e->revokeInvite()));a.add(leaderButton("Chuyển quyền",e->transfer()));a.add(leaderButton("Xóa thành viên",e->remove()));a.add(activeButton("Rời nhóm",e->leave()));p.add(a,BorderLayout.SOUTH);JSplitPane split=new JSplitPane(JSplitPane.VERTICAL_SPLIT,p,new JScrollPane(outgoingTable));split.setResizeWeight(.7);JPanel root=new JPanel(new BorderLayout());root.add(split);return root;}
        private JPanel requestsPanel(){JPanel p=panel(requestTable);JPanel a=new JPanel();a.add(leaderButton("Duyệt",e->decideJoin("approve")));a.add(leaderButton("Từ chối",e->decideJoin("reject")));p.add(a,BorderLayout.SOUTH);return p;}
        private JPanel blocksPanel(){JPanel p=panel(blockTable);p.add(leaderButton("Gỡ chặn",e->unblock()),BorderLayout.SOUTH);return p;}
        private JPanel handoverPanel(){JPanel p=panel(handoverTable);JPanel a=new JPanel();a.add(activeButton("Yêu cầu bàn giao",e->requestHandover()));a.add(leaderButton("Duyệt",e->decideHandover("approve")));a.add(leaderButton("Từ chối",e->decideHandover("reject")));p.add(a,BorderLayout.SOUTH);return p;}
        private JPanel settingsPanel(){JPanel form=new JPanel(new GridBagLayout());GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(6,6,6,6);c.fill=GridBagConstraints.HORIZONTAL;c.weightx=1;c.gridx=0;c.gridy=0;form.add(new JLabel("Tên nhóm"),c);c.gridy++;form.add(name,c);c.gridy++;form.add(new JLabel("Mô tả"),c);c.gridy++;form.add(new JScrollPane(description),c);c.gridy++;form.add(approval,c);c.gridy++;form.add(code,c);JPanel actions=new JPanel();actions.add(leaderButton("Lưu",e->save()));actions.add(leaderButton("Tạo lại mã",e->rotate()));actions.add(leaderButton("Thu hồi mã",e->revokeCode()));actions.add(leaderButton("Giải tán nhóm",e->disband()));c.gridy++;form.add(actions,c);JPanel p=new JPanel(new BorderLayout());p.add(form,BorderLayout.NORTH);return p;}
        private JPanel panel(JTable table){JPanel p=new JPanel(new BorderLayout());p.setBorder(BorderFactory.createEmptyBorder(8,8,8,8));p.add(new JScrollPane(table));return p;}

        private void refresh(){async(()->{JsonObject all=new JsonObject();JsonObject key=idData();all.add("detail",api.request("GROUP_DETAIL",key));if(isLeaderFrom(all.getAsJsonObject("detail"))){all.add("requests",api.request("GROUP_JOIN_REQUEST_LIST",key).get("requests"));all.add("blocks",api.request("GROUP_BLOCK_LIST",key).get("blocks"));JsonObject inv=new JsonObject();inv.addProperty("groupId",groupId);all.add("outgoing",api.request("GROUP_INVITATION_LIST",inv).get("invitations"));}all.add("handovers",api.request("GROUP_HANDOVER_LIST",key).get("handovers"));return all;},all->{detail=all.getAsJsonObject("detail");heading.setText(text(detail,"name")+" · "+role(detail));name.setText(text(detail,"name"));description.setText(text(detail,"description"));approval.setSelected(detail.has("approvalEnabled")&&detail.get("approvalEnabled").getAsBoolean());code.setText("Mã gia nhập: "+(detail.has("inviteCode")?text(detail,"inviteCode"):"(chỉ trưởng nhóm được xem)"));fill(members,detail.getAsJsonArray("members"),m->new Object[]{longValue(m,"userId"),text(m,"studentId"),text(m,"fullName"),text(m,"role"),m.get("online").getAsBoolean()?"Online":"Offline",text(m,"openTaskCount")});fill(requests,all.getAsJsonArray("requests"),r->new Object[]{longValue(r,"requestId"),longValue(r,"userId"),text(r,"studentId"),text(r,"fullName"),text(r,"status"),text(r,"requestedAt")});fill(blocks,all.getAsJsonArray("blocks"),b->new Object[]{longValue(b,"userId"),text(b,"studentId"),text(b,"fullName"),text(b,"blockedAt")});fill(outgoing,all.getAsJsonArray("outgoing"),i->new Object[]{longValue(i,"invitationId"),text(i,"studentId"),text(i,"fullName"),text(i,"status"),text(i,"expiresAt")});fill(handovers,all.getAsJsonArray("handovers"),h->new Object[]{longValue(h,"requestId"),longValue(h,"taskId"),longValue(h,"requestedBy"),text(h,"suggestedUserId"),text(h,"reason"),text(h,"status")});setEditable(isLeaderFrom(detail)&&"active".equals(text(detail,"status")));});}
        private boolean isLeaderFrom(JsonObject d){return d!=null&&"leader".equals(text(d,"role"));}
        private void setEditable(boolean leader){boolean active="active".equals(text(detail,"status"));name.setEditable(leader&&active);description.setEditable(leader&&active);approval.setEnabled(leader&&active);for(AbstractButton b:leaderButtons)b.setVisible(leader&&active);for(AbstractButton b:activeButtons)b.setEnabled(active);}
        private JButton leaderButton(String label,ActionListener listener){JButton b=button(label,listener);leaderButtons.add(b);return b;}
        private JButton activeButton(String label,ActionListener listener){JButton b=button(label,listener);activeButtons.add(b);return b;}
        private void invite(){String who=JOptionPane.showInputDialog(this,"Email hoặc MSSV");if(who==null)return;JsonObject d=idData();d.addProperty("identifier",who);call("GROUP_INVITE_CREATE",d);}
        private void revokeInvite(){int r=outgoingTable.getSelectedRow();if(r<0){warn("Chọn lời mời");return;}JsonObject d=new JsonObject();d.addProperty("invitationId",((Number)outgoing.getValueAt(r,0)).longValue());call("GROUP_INVITE_REVOKE",d);}
        private void transfer(){Long user=selected(members,memberTable,0);if(user==null)return;if(confirm("Chuyển quyền trưởng nhóm cho thành viên này?")){JsonObject d=idData();d.addProperty("userId",user);call("GROUP_ROLE_TRANSFER",d);}}
        private void remove(){Long user=selected(members,memberTable,0);if(user==null)return;if(confirm("Xóa và chặn thành viên này khỏi nhóm?")){JsonObject d=idData();d.addProperty("userId",user);d.addProperty("confirmed",true);call("GROUP_MEMBER_REMOVE",d);}}
        private void leave(){if(confirm("Bạn chắc chắn muốn rời nhóm?")){JsonObject d=idData();d.addProperty("confirmed",true);call("GROUP_LEAVE",d);}}
        private void decideJoin(String decision){Long id=selected(requests,requestTable,0);if(id==null)return;JsonObject d=new JsonObject();d.addProperty("requestId",id);d.addProperty("decision",decision);call("GROUP_JOIN_REQUEST_DECIDE",d);}
        private void unblock(){Long user=selected(blocks,blockTable,0);if(user==null)return;JsonObject d=idData();d.addProperty("userId",user);d.addProperty("confirmed",true);call("GROUP_MEMBER_UNBLOCK",d);}
        private void save(){JsonObject d=idData();d.addProperty("name",name.getText());d.addProperty("description",description.getText());d.addProperty("approvalEnabled",approval.isSelected());call("GROUP_UPDATE",d);}
        private void rotate(){call("GROUP_INVITE_CODE_ROTATE",idData());}private void revokeCode(){if(confirm("Thu hồi mã hiện tại?"))call("GROUP_INVITE_CODE_REVOKE",idData());}
        private void disband(){if(!confirm("Giải tán sẽ chuyển nhóm sang chế độ chỉ đọc. Tiếp tục?"))return;String n=JOptionPane.showInputDialog(this,"Nhập lại đúng tên nhóm để giải tán");if(n==null)return;JsonObject d=idData();d.addProperty("confirmed",true);d.addProperty("confirmName",n);call("GROUP_DISBAND",d);}
        private void requestHandover(){JTextField task=new JTextField(),suggested=new JTextField();JTextArea reason=new JTextArea(3,20);Object[] x={"Task ID",task,"User ID đề xuất (có thể trống)",suggested,"Lý do",new JScrollPane(reason)};if(JOptionPane.showConfirmDialog(this,x,"Yêu cầu bàn giao",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{JsonObject d=new JsonObject();d.addProperty("taskId",Long.parseLong(task.getText().trim()));if(!suggested.getText().isBlank())d.addProperty("suggestedUserId",Long.parseLong(suggested.getText().trim()));d.addProperty("reason",reason.getText());call("GROUP_HANDOVER_REQUEST",d);}catch(NumberFormatException e){warn("ID phải là số");}}
        private void decideHandover(String decision){Long id=selected(handovers,handoverTable,0);if(id==null)return;JsonObject d=new JsonObject();d.addProperty("requestId",id);d.addProperty("decision",decision);if("approve".equals(decision)){String user=JOptionPane.showInputDialog(this,"User ID nhận việc");if(user==null)return;try{d.addProperty("newUserId",Long.parseLong(user.trim()));}catch(NumberFormatException e){warn("User ID phải là số");return;}}else{String reason=JOptionPane.showInputDialog(this,"Lý do từ chối");if(reason==null)return;d.addProperty("reason",reason);}call("GROUP_HANDOVER_DECIDE",d);}
        private void call(String action,JsonObject data){async(()->api.request(action,data),o->refresh());}
        private JsonObject idData(){JsonObject d=new JsonObject();d.addProperty("groupId",groupId);return d;}
        private Long selected(DefaultTableModel model,JTable table,int column){int r=table.getSelectedRow();if(r<0){warn("Chọn một dòng");return null;}return ((Number)model.getValueAt(r,column)).longValue();}
        private boolean confirm(String text){return JOptionPane.showConfirmDialog(this,text,"Xác nhận",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION;}
        private void async(Callable<JsonObject> work,Consumer<JsonObject> done){status.setText("Đang xử lý...");new SwingWorker<JsonObject,Void>(){protected JsonObject doInBackground()throws Exception{return work.call();}protected void done(){try{done.accept(get());status.setText("Sẵn sàng");}catch(Exception e){Throwable t=e;while(t.getCause()!=null)t=t.getCause();String m=t instanceof ApiException a?friendly(a.code(),a.getMessage()):t.getMessage();status.setText("Lỗi: "+m);JOptionPane.showMessageDialog(GroupDialog.this,m,"Không thể thực hiện",JOptionPane.ERROR_MESSAGE);}}}.execute();}
        private void warn(String s){JOptionPane.showMessageDialog(this,s,"KTD Task Hub",JOptionPane.WARNING_MESSAGE);}
    }
}
